content.content:
/**
 * T009d live-backend witness.
 *
 * The pipeline's own witness machinery, OPERATED against a live loopback origin
 * instead of a static lane serve. Nothing in packages/ is changed: the crawl
 * reader, the outcome vocabulary, the emitter and the Playwright witness host
 * are all imported and driven exactly as runSynthesizedWitnessRealApp drives
 * them. The one thing that differs is the origin - pigallery2's own Express
 * backend, already up on 127.0.0.1, rendering its EJS index and answering its
 * own API - because the CLI's live-backend path is gated on a registered
 * AppSpec whose app name is in a closed admitted list, and adding pigallery2 to
 * it would be a packages/ change this unit is forbidden to make.
 *
 *   node --experimental-strip-types t009d-live-witness.mjs \
 *      <lane> <origin> <planFile> <derive|replay> <outFile>
 */
import { crawlLaneJourneys, CRAWL_DEFAULT_BOUNDS } from '../../../../packages/cli/src/witness/journey-synthesis/crawl.ts';
import { emitSynthesizedJourneys, completeSynthesizedJourney } from '../../../../packages/cli/src/witness/journey-synthesis/emit.ts';
import { routeLinkSelectors } from '../../../../packages/cli/src/witness/journey-synthesis/driver.ts';
import { createPlaywrightWitnessHost } from '../../../../packages/cli/src/witness/playwright-host.ts';
import { witnessChromiumExecutablePath } from '../../../../packages/cli/src/witness/browser.ts';
import { writeFileSync, readFileSync } from 'node:fs';

const [lane, origin, planFile, mode, outFile] = process.argv.slice(2);
const startedAt = Date.now();

/** The derivation happens ONCE, on the first lane, and is replayed on both. */
let derived;
if (mode === 'derive') {
  const reading = await crawlLaneJourneys(origin, CRAWL_DEFAULT_BOUNDS, fetch);
  derived = {
    journeys: reading.journeys,
    visited: reading.locality?.visited ?? reading.visited ?? null,
    locality: reading.locality ?? null,
  };
  writeFileSync(planFile, JSON.stringify(derived, null, 2));
} else {
  derived = JSON.parse(readFileSync(planFile, 'utf8'));
}

const emissions = emitSynthesizedJourneys(derived.journeys, { crawlBounds: CRAWL_DEFAULT_BOUNDS });

const host = createPlaywrightWitnessHost({
  chromiumExecutable: witnessChromiumExecutablePath(),
  contextProfile: 'current-witness',
});
const session = await host.browser.launch({ headless: true });

const urlIsRoute = (url, route) => {
  try {
    const u = new URL(url);
    return `${u.pathname}${u.search}${u.hash.startsWith('#/') ? u.hash : ''}` === route;
  } catch { return false; }
};

const journeys = [];
for (const emission of emissions) {
  if (!emission.replayable) {
    journeys.push({ name: emission.name, source: emission.source, specFile: emission.specFile, replayable: false, ran: false, outcomes: [] });
    continue;
  }
  const routes = emission.plan.routes;
  const first = routes[0] ?? '/';
  const page = await session.newPage();
  const consoleErrors = [];
  const consoleMessages = [];
  const pageErrors = [];
  page.onConsoleMessage((m) => { consoleMessages.push(`${m.level}: ${String(m.text).slice(0, 300)}`); if (m.level === 'error') consoleErrors.push(String(m.text).slice(0, 300)); });
  page.onPageError((e) => pageErrors.push(String(e.message ?? e).slice(0, 300)));
  await page.goto(new URL(first, origin).toString());
  // Give the Angular application its own time to bootstrap and fetch its gallery.
  // Two bounded waits, both allowed to time out and be measured either way:
  // the application mounting at all, and its gallery grid rendering the media
  // the backend indexed. Neither is an assertion; both are a bounded chance for
  // the running application to reach its own gallery surface.
  try { await page.waitForExpression('document.querySelector("app-pi-gallery2") && document.querySelector("app-pi-gallery2").childElementCount > 1', 15000); } catch { /* measured below either way */ }
  try { await page.waitForExpression('document.querySelectorAll("app-gallery-grid-photo").length > 0', 15000); } catch { /* measured below either way */ }
  const unreplayable = [];
  let routesReached = urlIsRoute(await page.evaluate('location.href'), first) ? 1 : 0;
  let routesWithoutOverflow = 0;
  const measureOverflow = async () => {
    const scroll = await host.viewportScroll();
    if (scroll.scrollHeight <= scroll.clientHeight) routesWithoutOverflow += 1;
  };
  await measureOverflow();
  const present = async (selector) => {
    try { await host.renderedStyles([{ label: 'synthesized', selector, properties: [] }]); return true; } catch { return false; }
  };
  for (const step of emission.plan.steps.slice(1)) {
    if (step.route !== undefined && step.route !== routes[0]) {
      let reached = false;
      for (const selector of routeLinkSelectors(step.route)) {
        if (!(await present(selector))) continue;
        try { await page.click(selector, 5000); reached = urlIsRoute(await page.evaluate('location.href'), step.route); }
        catch { reached = false; }
        if (reached) break;
      }
      if (reached) { routesReached += 1; await measureOverflow(); }
      else unreplayable.push(`route-not-reachable-by-link:${step.route}`);
      continue;
    }
    const selector = step.selector;
    if (selector === undefined) { unreplayable.push(`step-names-neither-route-nor-selector:${step.kind}`); continue; }
    if (!(await present(selector))) { unreplayable.push(`selector-absent-on-lane:${step.kind}`); continue; }
    try {
      if (step.kind === 'click') await page.click(selector, 5000);
      else if (step.kind === 'type') await page.type(selector, step.value ?? '', { clear: true, keyEvents: true }, 5000);
      else if (step.kind === 'press') await page.press(selector, step.value ?? 'Enter', 0, 5000);
    } catch { unreplayable.push(`gesture-refused-by-page:${step.kind}`); }
  }
  let selectorsPresent = 0;
  for (const selector of emission.plan.selectors) if (await present(selector)) selectorsPresent += 1;
  const measured = { routesReached, selectorsPresent, routesWithoutOverflow };
  const completed = completeSynthesizedJourney(emission, measured, { crawlBounds: CRAWL_DEFAULT_BOUNDS });
  // What the RUNNING application put on the page, read once, after the journey.
  const surface = await page.evaluate(`(() => ({
    title: document.title,
    baseHref: document.querySelector('base') ? document.querySelector('base').getAttribute('href') : null,
    baseResolved: document.baseURI,
    appRootPresent: document.querySelector('app-pi-gallery2') !== null,
    appRootChildElementCount: document.querySelector('app-pi-gallery2') ? document.querySelector('app-pi-gallery2').childElementCount : -1,
    serverInjectDefined: typeof window.ServerInject !== 'undefined',
    galleryComponentPresent: document.querySelector('app-gallery') !== null,
    gridPresent: document.querySelector('app-gallery-grid') !== null,
    photoTiles: document.querySelectorAll('app-gallery-grid-photo').length,
    photoImages: document.querySelectorAll('app-gallery-grid-photo img').length,
    thumbnailSrcs: [].slice.call(document.querySelectorAll('app-gallery-grid-photo img')).map(function (i) { return i.getAttribute('src'); }).slice(0, 8),
    navbarPresent: document.querySelector('app-gallery-navbar') !== null,
    visibleText: (document.body.innerText || '').trim().slice(0, 300),
    location: location.pathname + location.search + location.hash
  }))()`);
  journeys.push({
    name: emission.name, source: emission.source, specFile: emission.specFile,
    replayable: true, ran: true,
    routesDeclared: routes.length, routesReached, selectorsDeclared: emission.plan.selectors.length,
    selectorsPresent, routesWithoutOverflow,
    outcomes: [...completed.assertions],
    consoleMessages,
    unreplayableSteps: unreplayable,
    consoleErrors, pageErrors, surface,
  });
  await page.close();
}
await session.close();

